"""ADR assessment, clinician review, and MedWatch draft schemas."""

from enum import StrEnum
from typing import Any
from uuid import UUID

from pydantic import BaseModel, Field, model_validator

from app.models.enums import ADRStatus, MedWatchStatus, NaranjoCausality
from app.pharmacovigilance import (
    PATIENT_ANSWERABLE_NARANJO_QUESTIONS,
    NaranjoAnswer,
    NaranjoQuestion,
)


class ADRAssessmentRead(BaseModel):
    """Auto-generated by Pharmacovigilance Agent using Naranjo algorithm."""

    id: UUID
    patient_id: UUID
    symptom_report_id: UUID
    suspect_medication_id: UUID
    suspect_medication_name: str  # denormalized
    naranjo_score: int = Field(..., ge=-4, le=13)
    causality: NaranjoCausality
    naranjo_answers: dict[str, str] = Field(default_factory=dict)
    naranjo_assessment: dict[str, Any] = Field(default_factory=dict)
    evidence: list[dict[str, Any]] = Field(default_factory=list)
    thinking_chain: str | None = None  # Gemini Pro thinking trace
    status: ADRStatus = ADRStatus.DRAFT
    reviewed_by: UUID | None = None
    reviewed_at: str | None = None
    dismiss_reason: str | None = None
    created_at: str


class ADRReviewQueueItem(BaseModel):
    """Assigned-patient ADR evidence shown for clinician review.

    This intentionally excludes ``thinking_chain``. Clinicians receive the
    deterministic score inputs and patient-grounded evidence, not private model
    reasoning.
    """

    id: UUID
    patient_id: UUID
    patient_first_name: str
    patient_last_name: str
    symptom_report_id: UUID
    symptom: str
    severity: int = Field(..., ge=1, le=10)
    onset: str | None = None
    symptom_created_at: str
    suspect_medication_id: UUID
    suspect_medication_name: str
    naranjo_score: int = Field(..., ge=-4, le=13)
    causality: NaranjoCausality
    naranjo_answers: dict[str, str] = Field(default_factory=dict)
    naranjo_assessment: dict[str, Any] = Field(default_factory=dict)
    evidence: list[dict[str, Any]] = Field(default_factory=list)
    status: ADRStatus
    last_review_action: str | None = None
    review_note: str | None = None
    requested_information: list[str] = Field(default_factory=list)
    reviewed_by: UUID | None = None
    reviewed_at: str | None = None
    information_request_id: UUID | None = None
    information_request_status: str | None = None
    patient_responses: list[dict[str, Any]] = Field(default_factory=list)
    patient_responded_at: str | None = None
    created_at: str


class ADRReviewQueueResponse(BaseModel):
    """Clinician-scoped ADR review queue."""

    items: list[ADRReviewQueueItem]
    total: int = Field(..., ge=0)


class ADRReviewAction(StrEnum):
    """Clinician actions supported by the ADR review queue."""

    MARK_REVIEWED = "mark_reviewed"
    DISMISS = "dismiss"
    REQUEST_INFORMATION = "request_information"


class ADRReviewDecisionRequest(BaseModel):
    """A clinician decision or information request for a draft ADR assessment."""

    action: ADRReviewAction
    note: str | None = Field(default=None, max_length=2000)
    requested_information: list[NaranjoQuestion] = Field(default_factory=list, max_length=20)

    @model_validator(mode="after")
    def validate_action_details(self) -> "ADRReviewDecisionRequest":
        self.note = self.note.strip() if self.note else None
        self.requested_information = list(dict.fromkeys(self.requested_information))
        if (
            self.action in {ADRReviewAction.DISMISS, ADRReviewAction.REQUEST_INFORMATION}
            and not self.note
        ):
            raise ValueError("A review note is required for this action")
        if self.action is ADRReviewAction.REQUEST_INFORMATION:
            if not self.requested_information:
                raise ValueError("Select at least one patient-answerable question")
            unsafe = set(self.requested_information) - PATIENT_ANSWERABLE_NARANJO_QUESTIONS
            if unsafe:
                raise ValueError(
                    "Information requests may contain only patient-answerable questions"
                )
        elif self.requested_information:
            raise ValueError("Requested information is only valid for information requests")
        return self


class ADRReviewDecisionResponse(BaseModel):
    """Persisted result of an auditable clinician ADR review action."""

    id: UUID
    patient_id: UUID
    status: ADRStatus
    last_review_action: ADRReviewAction
    review_note: str | None = None
    requested_information: list[str] = Field(default_factory=list)
    reviewed_by: UUID
    reviewed_at: str
    dismiss_reason: str | None = None
    updated_at: str


class ADRInformationRequestStatus(StrEnum):
    """Lifecycle for one clinician-to-patient ADR follow-up request."""

    PENDING = "pending"
    ANSWERED = "answered"
    CANCELLED = "cancelled"


class ADRInformationAnswer(BaseModel):
    """One confirmed patient answer about an event that already happened."""

    question: NaranjoQuestion
    answer: NaranjoAnswer
    evidence: str | None = Field(default=None, max_length=500)

    @model_validator(mode="after")
    def validate_patient_answer(self) -> "ADRInformationAnswer":
        if self.question not in PATIENT_ANSWERABLE_NARANJO_QUESTIONS:
            raise ValueError("This question cannot be answered through the patient follow-up")
        self.evidence = self.evidence.strip() if self.evidence else None
        if self.answer is not NaranjoAnswer.DO_NOT_KNOW and not self.evidence:
            raise ValueError("Describe what happened for yes or no answers")
        return self


class ADRInformationResponseRequest(BaseModel):
    """Patient-confirmed answers to one pending clinician information request."""

    answers: list[ADRInformationAnswer] = Field(..., min_length=1, max_length=3)
    confirmed: bool

    @model_validator(mode="after")
    def validate_confirmation(self) -> "ADRInformationResponseRequest":
        if not self.confirmed:
            raise ValueError("Confirm the answers before sending them to the care team")
        questions = [item.question for item in self.answers]
        if len(questions) != len(set(questions)):
            raise ValueError("Each requested question may be answered once")
        return self


class ADRInformationRequestRead(BaseModel):
    """Pending patient-safe ADR follow-up shown in the patient portal."""

    id: UUID
    adr_assessment_id: UUID
    symptom: str
    symptom_severity: int = Field(..., ge=1, le=10)
    suspect_medication_name: str
    requested_information: list[NaranjoQuestion]
    patient_message: str
    current_naranjo_score: int = Field(..., ge=-4, le=13)
    current_causality: NaranjoCausality
    status: ADRInformationRequestStatus
    created_at: str


class ADRInformationResponseRead(BaseModel):
    """Updated deterministic assessment after confirmed patient answers."""

    request_id: UUID
    adr_assessment_id: UUID
    status: ADRInformationRequestStatus
    naranjo_score: int = Field(..., ge=-4, le=13)
    causality: NaranjoCausality
    responded_at: str


class MedWatchEvidenceReference(BaseModel):
    """Attribution for one or more fields in an editable MedWatch draft."""

    field_paths: list[str] = Field(..., min_length=1)
    source_type: str
    source_id: UUID | None = None
    attribution: str
    excerpt: str | None = None
    citation: str | None = None


class MedWatchPatientSection(BaseModel):
    patient_identifier: str = ""
    date_of_birth: str = ""
    sex: str = ""


class MedWatchEventSection(BaseModel):
    description: str = ""
    onset_date_or_time: str = ""
    outcome: str = ""
    seriousness: str = ""


class MedWatchProductSection(BaseModel):
    name: str = ""
    dose: str = ""
    frequency: str = ""
    route: str = ""
    therapy_start_date: str = ""
    therapy_end_date: str = ""


class MedWatchConcomitantProductsSection(BaseModel):
    products: str = ""


class MedWatchTestsHistorySection(BaseModel):
    relevant_tests: str = ""
    other_relevant_history: str = ""


class MedWatchReporterSection(BaseModel):
    name: str = ""
    email: str = ""
    specialty: str = ""
    clinic_name: str = ""


class MedWatchClinicalReviewSection(BaseModel):
    naranjo_score: int = Field(..., ge=-4, le=13)
    causality: NaranjoCausality
    reportability_rationale: str = Field(..., min_length=1, max_length=2000)


class MedWatchFormData(BaseModel):
    """Editable MedWatch-compatible fields. Empty strings explicitly mean unknown."""

    patient: MedWatchPatientSection
    event: MedWatchEventSection
    suspect_product: MedWatchProductSection
    concomitant_products: MedWatchConcomitantProductsSection
    tests_and_history: MedWatchTestsHistorySection
    reporter: MedWatchReporterSection
    clinical_review: MedWatchClinicalReviewSection


class MedWatchPreparationDecision(StrEnum):
    PREPARE_DRAFT = "prepare_draft"


class MedWatchDraftCreateRequest(BaseModel):
    """Explicit clinician decision to prepare, but not file, a MedWatch draft."""

    decision: MedWatchPreparationDecision
    reportability_rationale: str = Field(..., min_length=1, max_length=2000)

    @model_validator(mode="after")
    def strip_rationale(self) -> "MedWatchDraftCreateRequest":
        self.reportability_rationale = self.reportability_rationale.strip()
        if not self.reportability_rationale:
            raise ValueError("A reportability rationale is required")
        return self


class MedWatchDraftUpdateRequest(BaseModel):
    form_data: MedWatchFormData
    expected_revision: int = Field(..., ge=1)


class MedWatchDraftApprovalRequest(BaseModel):
    approval_note: str = Field(..., min_length=1, max_length=2000)
    expected_revision: int = Field(..., ge=1)
    attested: bool

    @model_validator(mode="after")
    def validate_attestation(self) -> "MedWatchDraftApprovalRequest":
        self.approval_note = self.approval_note.strip()
        if not self.approval_note:
            raise ValueError("An approval note is required")
        if not self.attested:
            raise ValueError("Clinician attestation is required")
        return self


class MedWatchDraftRead(BaseModel):
    """Editable draft with evidence attribution and reviewer state."""

    id: UUID
    adr_assessment_id: UUID
    patient_id: UUID
    form_data: MedWatchFormData
    source_evidence: list[MedWatchEvidenceReference] = Field(default_factory=list)
    clinician_edited_fields: list[str] = Field(default_factory=list)
    de_identified: bool = False
    status: MedWatchStatus = MedWatchStatus.DRAFT
    created_by: UUID | None = None
    approved_by: UUID | None = None
    approved_at: str | None = None
    approval_note: str | None = None
    revision: int = Field(..., ge=1)
    export_version: str
    created_at: str
    updated_at: str


class MedWatchDraftListResponse(BaseModel):
    items: list[MedWatchDraftRead]
    total: int = Field(..., ge=0)


class MedWatchDraftExportResponse(BaseModel):
    """Approved export artifact. It is not proof of an FDA filing."""

    filename: str
    media_type: str = "application/json"
    content: dict[str, Any]


# Backward-compatible public model name used by app.models.
MedWatchDraft = MedWatchDraftRead
